--**********************************
--雕纹调度接口
--**********************************
function x900014_DoDiaowenAction( sceneId, selfId, DataType,arg1,arg2,arg3 )
	if GetLevel(sceneId,selfId) < 52 then
		x900014_NotifyTip( sceneId, selfId, "你的江湖历练不够啊，请到52级以后再来找我吧！")
	    return
	end
	if DataType == 1 then
		x900014_DWShike( sceneId, selfId, arg1,arg2,arg3 )
		return
	end
	if DataType == 2 then --雕纹强化
		x900014_DWQiangHua(sceneId,selfId,arg1,arg2,arg3)
		return
	end
	if DataType == 3 then --雕纹拆除
		x900014_DWChaiChu(sceneId,selfId,arg1,arg2,arg3)
		return
	end
	if DataType == 5 then --雕纹融合
		x900014_DWRongHe(sceneId,selfId,arg1,arg2,arg3)
		return
	end
	if DataType == 8 then
		x900014_DWHecheng( sceneId, selfId, arg1)
		return
	end
	if DataType == 99 then --直接升级雕纹
		x900014_DWLeveUp(sceneId,selfId,arg1,arg2,arg3)
		return
	end
	if DataType == 100 then --直接升级雕纹
		x900014_DWDivert(sceneId,selfId,arg1,arg2)
		return
	end
	if DataType == 101 then --购买熔金粉提示【直接买】
		x900014_BuyItem_OK(sceneId,selfId,0)
		return
	end
	if DataType == 102 then --购买熔金粉提示
		x900014_BuyItem_OK(sceneId,selfId,1)
	end
	if DataType == 103 then --雕纹拆解用
		x900014_DWChaiJie(sceneId,selfId,arg1)
		return
	end
end
--溶剂购买
function x900014_DWShikeBeginPay(sceneId,selfId,nCheck)
	if nCheck ~= 0 and nCheck ~= 1 then
		return
	end
	LuaFnBuyNotEnoughMaterial(sceneId,selfId,30503149,1,nCheck)
end
--**********************************
--暗器雕纹摘除
--**********************************
function x900014_DWChaiChu_Dark(sceneId,selfId,nPos_1,nPos_2,nSelect)
	local nMaterial = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos_2 )
	local nDarkDW = GetMissionData(sceneId,selfId,EQUIP_ANQI_DATA_3);
	local nData = "&DW"
	local nDW_1 = mod(nDarkDW,1000);
	local nDW_2 = mod(floor(nDarkDW/1000),1000);
	local nDW_1_Name = x900014_DWInfo_Dark[nDW_1]
	local nDW_1_Data,nDW_2_Data = mod(nDarkDW,1000),mod(floor(nDarkDW/1000),1000)
	if nDW_1 ~= 0 then
		nDW_1 = x900014_DW_Dark[nDW_1_Name]
	end
	if nDW_2 ~= 0 then
		nDW_2 = x900014_DW_Dark[x900014_DWInfo_Dark[nDW_2]]
	end
	if nDW_1 ~= "" then
		nData = nData..nDW_1
	else
		nData = nData.."000"
	end
	if nDW_2 ~= "" then
		nData = nData..nDW_2
	else
		nData = nData.."000"
	end
	
	local pos1,pos2,nType_1,nData_1,nType_2,nData_2 = strfind( nData,x900014_DW_DWSIGIN)
	if pos1 == nil or pos2 == nil then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_19}")--请放入一件已镶嵌了雕纹的装备。
		return
	end
	if nSelect == 2 then --双极雕纹啊
		if tonumber(nData_2) == 0 then
			x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_55}")--H请选择您要想要摘除的雕纹。
			return
		end
	end
	local nDWID_1,nDWID_2 = Lua_GetEquipDiaowenID(sceneId,selfId,nPos_1,nData)
	local nFinalItem = 0
	if nSelect == 1 then
		if nDW_2 ~= nil then --md，才发现原来写法有问题，现在改也成问题了= = 就这样吧
			x900014_NotifyTip( sceneId, selfId, "请先行摘除第二个雕纹" )
			return
		end
		nFinalItem = nDWID_1
		nType_1 = "0"
		nData_1 = "00"
	else
		--第二个雕纹
		nFinalItem = nDWID_2
		nType_2 = "0"
		nData_2 = "00"
	end
	if nFinalItem == 0 then
		x900014_NotifyTip( sceneId, selfId, "没有雕纹可以摘除" )
		return
	end
	if CostMoney(sceneId, selfId, x900014_g_needMoeny) == -1 then
		x900014_NotifyTip( sceneId, selfId, "#{ResultText_154}" )
		return
	end
	--
	local nDWIndex = 0
	for i = 1,getn(x900014_DWInfo_Dark) do
		if x900014_DWInfo_Dark[i] == nFinalItem then
			nDWIndex = i;
			break;
		end
	end
	local nFinalData = 0;
	if nDarkDW >= 1000 then
		nFinalData = mod(nDarkDW,1000)
	else
		nFinalData = 0
	end
--	x900014_NotifyTip( sceneId, selfId,tonumber(nFinalData) )
	SetMissionData(sceneId,selfId,EQUIP_ANQI_DATA_3,tonumber(nFinalData))
	--
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	LuaFnDelAvailableItem(sceneId,selfId,nMaterial,1)
	local nPos = TryRecieveItem(sceneId,selfId,nFinalItem,1)
	LuaFnItemBind(sceneId,selfId,nPos);
	
	if nSelect == 2 then --这里之前有一次双极雕纹校验
		TryRecieveItem(sceneId,selfId,38001003,1) --雕纹融合符
	end
	x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_56}" )
	local nGlobalMsg = ""
	if nSelect == 2 then
		nGlobalMsg = format("#{_INFOUSR%s}#H拿着%s端详良久，终于将#Y熔金粉#H缓缓洒下，一阵光华闪动，只见一个#Y雕纹融合符#H和#Y%s#H完好无损的呈现在眼前。",
							GetName(sceneId,selfId),
							GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos_1 )),
							GetItemName(sceneId,nFinalItem)
							)
	end
	AddGlobalCountNews(sceneId,nGlobalMsg);
end
--**********************************
--暗器雕纹升级
--**********************************
function x900014_DWLeveUp_Dark(sceneId,selfId,nPos,Num)
    local HaveJSC = LuaFnGetAvailableItemCount(sceneId,selfId,20310166)
	if Num > HaveJSC then
	   x900014_NotifyTip( sceneId, selfId, "金蚕丝不足，无法进行操作！")
	   return
	end
	local DarkId = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos )
	-- AddGlobalCountNews(sceneId,"DarkId:"..DarkId)
	local nHave = GetMissionData(sceneId,selfId,MD_DWDARKJCS)
	local nDarkDWData = mod(DarkId,10)
	local nType_1,nLevel_1,nHaveItem  = "D",nDarkDWData,nHave
	--意外处理下
	if nLevel_1 == 0 then
	   x900014_NotifyTip( sceneId, selfId, "暗器体力雕纹已经满级。")
	   return
	end			
	--得到等级需要金蚕丝数量
	local nDWneed = 0
	local nDWLeve = 0
	local nDWduoyu = 0
	   nDWneed = x900014_DWInfo[nType_1][nLevel_1][2]	   
	   if nDWneed > Num + nHaveItem then -- 2+1=3 9 >3 
	       nDWLeve = nLevel_1--2
		   nDWduoyu = Num + nHaveItem-- 11-3
	   end	      
	   if nDWneed == Num + nHaveItem then -- 2+1=3 9 >3 
	       nDWLeve = nLevel_1 + 1--2
		   nDWduoyu = 0-- 11-3
	   end
	   if nDWneed < Num + nHaveItem then -- 2+1=3 9 >3 
	       nDWLeve = nLevel_1 + 1--2
		   nDWduoyu = (Num + nHaveItem) - nDWneed-- 11-3
	   end
	   -- AddGlobalCountNews(sceneId,"nDWneed:"..nDWneed)
	   -- AddGlobalCountNews(sceneId,"Num + nHaveItem:"..Num + nHaveItem)
	local ret = LuaFnDelAvailableItem(sceneId,selfId,20310166,Num)
	if ret ~= 1 then
	   x900014_NotifyTip( sceneId, selfId, "金蚕丝扣除失败，无法进行强化。")
	   return
	end
	if nDWLeve > nLevel_1 then
	  local nNewDatkid = 10155010 + nDWLeve			
      LuaFnEquipTransToNew(sceneId, selfId,nPos,nNewDatkid)
	  SetMissionData(sceneId,selfId,MD_DWDARKJCS,0)
	end
	SetMissionData(sceneId,selfId,MD_DWDARKJCS,nDWduoyu)
    x900014_NotifyTip( sceneId, selfId, "恭喜您，雕纹强化成功")
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	local nGlobalMsg = ""
	local szItemTransfer = GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos ))
	if nDWLeve > tonumber(nLevel_1) then
	nGlobalMsg = format("#H#{_INFOUSR%s}在#G洛阳#{_INFOAIM152,101,0,张降龙}#Y张降龙#H处，成功使用#G雕纹升级#H功能将蚀刻在#Y%s#H上的#Y%s#H升级到了#G%s级#H。",
					GetName(sceneId,selfId),
					szItemTransfer,
					x900014_DWInfo[nType_1][tonumber(nLevel_1)][1],
					tonumber(nDWLeve))
    AddGlobalCountNews(sceneId,nGlobalMsg)					
	end				
end
--**********************************
--暗器雕纹融合
--对应关系，鉴定，材料均已检查
--**********************************
function x900014_DoDiaowenAction_Dark_RongHe(sceneId,selfId,nPos,nMaterialPos,nDWPos)
	local nMaterial = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nMaterialPos )
	local nDiaoWen = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nDWPos )
	local nDWIndex = 0
	for i = 1,getn(x900014_DWInfo_Dark) do
		if x900014_DWInfo_Dark[i] == nDiaoWen then
			nDWIndex = i;
			break;
		end
	end
	if nDWIndex == 0 then
		x900014_NotifyTip( sceneId, selfId, "雕纹数据异常，请联系极致天龙运营团队 E-DARK-03")
		return
	end
	--校验雕纹类型
	local nDW_Head = x900014_DW_ToTable[nDiaoWen]
	if nDW_Head == nType_1 then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_47}" )--H只有相同装备位、不同颜色的两个雕纹才能进行融合。
		return
	end
	
	local nDarkDW = GetMissionData(sceneId,selfId,EQUIP_ANQI_DATA_3);
	local nData = "&DW"
	local nDW_1 = mod(nDarkDW,1000);
	local nDW_2 = mod(floor(nDarkDW/1000),1000);
	local nDW_1_Name = x900014_DWInfo_Dark[nDW_1]
	if nDW_1 ~= 0 then
		nDW_1 = x900014_DW_Dark[nDW_1_Name]
	end
	if nDW_2 ~= 0 then
		nDW_2 = x900014_DW_Dark[x900014_DWInfo_Dark[nDW_2]]
	end
	if nDW_1 ~= 0 then
		nData = nData..nDW_1
	else
		nData = nData.."000"
	end
	if nDW_2 ~= 0 then
		nData = nData..nDW_2
	else
		nData = nData.."000"
	end
	
--	x900014_NotifyTip( sceneId, selfId, "nData "..nData )
	local pos1,pos2,nType_1,nData_1,nType_2,nData_2 = strfind( nData,x900014_DW_DWSIGIN)
	if pos1 == nil or pos2 == nil then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_44}")--H请先放入已蚀刻了一个雕纹的装备。
		return
	end
	--校验雕纹类型
	--local nDW_Head = mod(floor(nDiaoWen/10),1000)
	local nDW_Head = x900014_DW_ToTable[nDiaoWen]
	if nDW_Head == nType_1 then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_47}" )--H只有相同装备位、不同颜色的两个雕纹才能进行融合。
		return
	end
	nDW_2 = nDWIndex * 1000
	local nFinalData = nDW_2 + mod(nDarkDW,1000);
	--x900014_NotifyTip( sceneId, selfId, "nFinalData "..nFinalData )
	SetMissionData(sceneId,selfId,EQUIP_ANQI_DATA_3,nFinalData);
	LuaFnDelAvailableItem(sceneId,selfId,nMaterial,1)
	LuaFnDelAvailableItem(sceneId,selfId,nDiaoWen,1)
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_52}" )
	local szItemTransfer = GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos ))
	local nGlobalMsg = format("#H#{_INFOUSR%s}潜心钻研雕纹之奥秘，仅用一张#{_ITEMINFO38001002}，便成功地将#Y%s#H与已蚀刻在%s之上的#Y%s#H融合为#Y双极雕纹#H，此举之妙令众人赞叹不已！",
		GetName(sceneId,selfId),
		GetItemName(sceneId,nDiaoWen),
		szItemTransfer,
		GetItemName(sceneId,nDW_1_Name)
		)
	AddGlobalCountNews(sceneId,nGlobalMsg);
end
--**********************************
--暗器雕纹蚀刻
--对应关系，鉴定，材料均已检查
--**********************************
function x900014_DoDiaowenAction_Dark(sceneId,selfId,nPos,nMaterialPos,nDWPos)
	local nMaterial = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nMaterialPos )
	local nDiaoWen = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nDWPos )
	local ItemIndex = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos )
	local DarkDiaoWen = {
	30110441,30110442,30110443,30110444,30110445,30110446,30110447,30110448,30110449,30110450,
	}
    if ItemIndex ~= 10155003 then
	   x900014_NotifyTip( sceneId, selfId, "目前只有冰魄神针支持雕纹或已雕纹")
	   return
	end	
	local nDWIndex = 0
	for i = 1,getn(DarkDiaoWen) do
		if DarkDiaoWen[i] == nDiaoWen then
			nDWIndex = i;
			break;
		end
	end
	if nDWIndex == 0 then
		x900014_NotifyTip( sceneId, selfId, "暗器雕纹目前只支持体力雕纹")
		return
	end
	LuaFnEquipTransToNew(sceneId, selfId,nPos,10155011)
	LuaFnDelAvailableItem(sceneId,selfId,nDiaoWen,1)--扣除雕纹
	LuaFnDelAvailableItem(sceneId,selfId,nMaterial,1)--扣除雕纹
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	x900014_NotifyTip( sceneId, selfId, "恭喜你，蚀刻成功！" )
end
