--**********************************
--雕纹拆除
--**********************************
function x900014_DWChaiChu(sceneId,selfId,nPos_1,nPos_2,nSelect)
	if nSelect ~= 1 and nSelect ~= 2 then
		return
	end
	local EquipType_1 = LuaFnGetBagEquipType( sceneId, selfId, nPos_1 )
	if EquipType_1 == 17 then
		x900014_NotifyTip( sceneId, selfId, "暗器暂不支持雕纹拆除")
		return
	end	
	if nPos_1 < 0 or nPos_1 > 29 then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_19}")
		return
	end
	if nPos_2 < 0 or nPos_2 > 29 then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_20}")
		return
	end
	if LuaFnGetPropertyBagSpace( sceneId, selfId) < 2  then
		x900014_NotifyTip( sceneId, selfId,"#{SSXDW_140819_58}" ) --H背包道具栏空位不足，请至少留出两个空位。
		return 		 
	end
	local nMaterial = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos_2 )
	if nMaterial ~= 30503150 then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_20}") --必须放入熔金粉
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, nPos_2) ~= 0 then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_42}")--该物品已经加锁，不可进行该操作
		return
	end
	local _,nCreaterData = LuaFnGetItemCreator(sceneId, selfId, nPos_1);
	if nCreaterData == nil then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_19}")--请放入一件已镶嵌了雕纹的装备。
		return
	end
	local pos1,pos2,nType_1,nData_1,nType_2,nData_2 = strfind( nCreaterData,x900014_DW_DWSIGIN)
	if pos1 == nil or pos2 == nil then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_19}")--请放入一件已镶嵌了雕纹的装备。
		return
	end
	if nSelect == 2 then --双极雕纹啊
		if tonumber(nData_2) == 0 then
			x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_55}")--H请选择您要想要摘除的雕纹。
			return
		end
	end
	local nDWID_1,nDWID_2 = Lua_GetEquipDiaowenID(sceneId,selfId,nPos_1,nCreaterData)
	local nFinalItem = 0
	if nSelect == 1 then
		-- if nType_2 ~= "0" then --md，才发现原来写法有问题，现在改也成问题了= = 就这样吧
			-- x900014_NotifyTip( sceneId, selfId, "请先行摘除第二个雕纹" )
			-- return
		-- end
		nFinalItem = nDWID_1
		nType_1 = "0"
		nData_1 = "00"
		nData_2 = "0000"
	-- else
		-- --第二个雕纹
		-- nFinalItem = nDWID_2
		-- nType_2 = "0"
		-- nData_2 = "00"
	end
	if nFinalItem == 0 then
		x900014_NotifyTip( sceneId, selfId, "没有雕纹可以摘除" )
		return
	end
	if CostMoney(sceneId, selfId, x900014_g_needMoeny) == -1 then --5J扣钱
		x900014_NotifyTip( sceneId, selfId, "#{ResultText_154}" )
		return
	end
	local nFinalData = gsub(nCreaterData,"&DW%w%w%w%w%w%w","&DW"..nType_1..nData_1..nData_2)
	LuaFnSetEquipItemCreatorEx( sceneId, selfId, nPos_1, nFinalData)
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	LuaFnDelAvailableItem(sceneId,selfId,nMaterial,1)
	local nPos = TryRecieveItem(sceneId,selfId,nFinalItem,1)
	LuaFnItemBind(sceneId,selfId,nPos);
	 if nDWID_2 > 0 then --金蚕丝也要拆除下来的
	   BeginAddItem(sceneId)
	   AddItem( sceneId,20310166, nDWID_2 )
	   EndAddItem(sceneId,selfId)
	   AddItemListToHuman(sceneId,selfId)
	 end
	x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_56}" )
	local nGlobalMsg = ""
	if nSelect == 2 then
		nGlobalMsg = format("#{_INFOUSR%s}#H拿着%s端详良久，终于将#Y熔金粉#H缓缓洒下，一阵光华闪动，只见一个#Y雕纹融合符#H和#Y%s#H完好无损的呈现在眼前。",
							GetName(sceneId,selfId),
							GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos_1 )),
							GetItemName(sceneId,nFinalItem)
							)
	end
	AddGlobalCountNews(sceneId,nGlobalMsg);
end
