--**********************************
--雕纹拆解
--**********************************
function x900014_DWChaiJie(sceneId,selfId,nPos)
	local nDiaoWen = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos )
	if x900014_DWValue[nDiaoWen] == nil then
		x900014_NotifyTip( sceneId, selfId, "#{DWCJJ_140606_13}")--请放入雕纹。
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, nPos) ~= 0 then
		x900014_NotifyTip( sceneId, selfId, "#{DWCJJ_140606_14}")--H雕纹已加锁，无法进行拆解
		return
	end
	--x900014_DWChaiJieInfo
	local nDiaoWenType = 1
	local DWName = GetItemName(sceneId,nDiaoWen)
	local nPos_1 = strfind(DWName,"抗")--此处着实无奈啊，配表没搞好，共军太狡猾！！！！
	if nPos_1 ~= nil then
		nDiaoWenType = 3
		local nPos_2 = strfind(DWName,"减")
		if nPos_2 ~= nil then
			nDiaoWenType = 2
		end
	end
	local JCSNum,nYuanBaoNeed = 0,0
	local nDiaoWenLevel = mod(nDiaoWen,10)
	if nDiaoWenLevel == 0 then --0就是10级
		nDiaoWenLevel = 10
	end
	if nDiaoWenType==1 then--普通
		nYuanBaoNeed = x900014_DWChaiJieInfo[nDiaoWenLevel].normal[1]
		JCSNum = x900014_DWChaiJieInfo[nDiaoWenLevel].normal[2]
	elseif nDiaoWenType==2 then--减抗
		nYuanBaoNeed = x900014_DWChaiJieInfo[nDiaoWenLevel].jiankang[1]
		JCSNum = x900014_DWChaiJieInfo[nDiaoWenLevel].jiankang[2]
	elseif nDiaoWenType==3 then--抗性
		nYuanBaoNeed = x900014_DWChaiJieInfo[nDiaoWenLevel].kangxing[1]
		JCSNum = x900014_DWChaiJieInfo[nDiaoWenLevel].kangxing[2]
	end
	local nYuanBao = YuanBao(sceneId,selfId,selfId,3,0)
	if nYuanBao < nYuanBaoNeed then
		x900014_NotifyTip( sceneId, selfId, "#{DWCJJ_140606_15}")--H您的元宝数量不足，无法进行拆解。
		return
	end
	local needSpace = ceil(JCSNum/200)
	if LuaFnGetMaterialBagSpace( sceneId, selfId) < needSpace  then
		x900014_NotifyTip( sceneId, selfId,"您当前背包材料栏空间不足，请至少保留"..needSpace.."个空位。" ) --H您当前背包材料栏空间不足，请至少保留1个空位。
		return 		 
	end
	local delitem1 = LuaFnEraseItem(sceneId,selfId,nPos)
	if delitem1 < 1 then
		x900014_NotifyTip( sceneId, selfId, "雕纹拆解失败！请联系极致天龙运营团队！" )
		return
	end
	BeginAddItem(sceneId)
	AddItem( sceneId,20310166, JCSNum )
	EndAddItem(sceneId,selfId)
	AddItemListToHuman(sceneId,selfId)
--	for i = 1,JCSNum do
--		TryRecieveItem(sceneId,selfId,20310168,1)
--	end
	-- LuaFnCostYuanBao(sceneId,selfId,nYuanBaoNeed)
	YuanBao(sceneId,selfId,-1,2,nYuanBaoNeed)
	x900014_NotifyTip( sceneId, selfId, "成功拆解1个"..DWName.."#H，获得"..JCSNum.."个金蚕丝")
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
end
--**********************************
--雕纹转移
--**********************************
function x900014_DWDivert(sceneId,selfId,arg1,arg2)
	if arg2 < 0 or arg2 > 29 or arg1 < 0 or arg1 > 29 then
		x900014_NotifyTip( sceneId, selfId,"#{DWZY_141216_22}")
		return
	end
	local EquipType_1 = LuaFnGetBagEquipType( sceneId, selfId, arg1 )
	local EquipType_2 = LuaFnGetBagEquipType( sceneId, selfId, arg2 )
	if EquipType_1 == 17 then
		x900014_NotifyTip( sceneId, selfId,"暗器暂不支持雕纹转移")
		return
	end
	if EquipType_1 == 2 or EquipType_1 == 8 or EquipType_2 == 2 or EquipType_2 == 8 then
		x900014_NotifyTip( sceneId, selfId,"#{DWZY_141216_22}") --请放入一件装备。
		return
	end
	if EquipType_2 == 17 then
		x900014_NotifyTip( sceneId, selfId, "暂不支持暗器雕纹")
		return
	end
	local ItemLevel_1 = GetBagItemLevel(sceneId, selfId, arg1) --目标装备等级
	if ItemLevel_1 < 50 then
		x900014_NotifyTip( sceneId, selfId,"#{DWZY_141216_25}") --只有50级及以上的装备才可以进行雕纹转移操作。
		return
	end
	local ItemLevel_2 = GetBagItemLevel(sceneId, selfId, arg2) --目标装备等级
	if ItemLevel_2 < 50 then
		x900014_NotifyTip( sceneId, selfId,"#{DWZY_141216_37}") --目标装备等级需要大于等于50级方可进行雕纹转移操作。
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, arg1) ~= 0 then
		x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_27}")--该装备尚处于锁定状态，无法转移该装备上蚀刻的雕纹。
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, arg2) ~= 0 then
		x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_32}")--要进行雕纹转移的装备尚处于锁定状态，无法进行转移。
		return
	end
	if EquipType_1 ~= EquipType_2 then
		x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_36}")--只有同类型的装备之间才可以进行雕纹转移。
		return
	end
--	local ret_judge = LuaFnIsJudgeApt( sceneId, selfId, arg2 )
--	if ret_judge ~= 1 then
--		x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_43}")--该装备尚未鉴定，无法向其上转移雕纹
--		return
--	end
	--///////////A
	local _,nCreaterData_1 = LuaFnGetItemCreator(sceneId, selfId, arg1);
	if nCreaterData_1 == nil then
		x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_31}")--只有蚀刻了雕纹的装备才能进行雕纹转移。
		return
	end
	local pos1,pos2,AnType_1,AnData_1,AnData_2 = strfind( nCreaterData_1,x900014_DW_DWSIGIN)
	if pos1 == nil or pos2 == nil then
		x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_31}")
		return
	end
	--///////////B
	local _,nCreaterData_2 = LuaFnGetItemCreator(sceneId, selfId, arg2);
	if nCreaterData_2 ~= nil and nCreaterData_2 ~= "" then
		local pos1,pos2 = strfind( nCreaterData_2,x900014_DW_DWSIGIN)
		if pos1 ~= nil and pos2 ~= nil then
			x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_35}")--目标装备上已经蚀刻了雕纹，无法进行转移操作。
			return
		end
	end
	if nCreaterData_2 == nil then
		nCreaterData_2 = ""
	end
	if CostMoney(sceneId, selfId, x900014_g_needMoeny_ZY) == -1 then --20J扣钱
		x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_40}" )
		return
	end
	local nFinalData_1 = gsub(nCreaterData_1,"&DW%w%w%w%w%w%w%w","")
	local nFinalData_2 = nCreaterData_2.."&DW"..AnType_1..AnData_1..AnData_2
	LuaFnSetEquipItemCreatorEx( sceneId, selfId, arg1, nFinalData_1)
	LuaFnSetEquipItemCreatorEx( sceneId, selfId, arg2, nFinalData_2)
	--目标装备绑定
	LuaFnItemBind(sceneId,selfId,arg2);
	
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	x900014_NotifyTip( sceneId, selfId, "#{DWZY_141216_41}" )--雕纹转移成功。
	local nGlobalMsg = ""
	nGlobalMsg = format("#H#{_INFOUSR%s}在#G洛阳#{_INFOAIM318,315,0,张降龙}#Y张降龙#H的指点下，将#Y%s#H上的雕纹转移到了#Y#%s#H上，只见一道七彩光柱冲天而起，良久后才渐渐消散。",
				GetName(sceneId,selfId),
				GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, arg1 )),
				GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, arg2 )))
	AddGlobalCountNews(sceneId,nGlobalMsg);
end
--**********************************
--雕纹升级
--**********************************
function x900014_DWLeveUp(sceneId,selfId,nPos,iToLevelSel,iToLevelSelEx)
	if iToLevelSel<=0 and iToLevelSelEx <=0 then--未选择升级哪个
		x900014_NotifyTip( sceneId, selfId,"#{DWSJ_141202_23}") --请选择想要升级的雕纹等级。
		return
	end
	if nPos < 0 then
		x900014_NotifyTip( sceneId, selfId, "#{DWSJ_141202_21}")--请放入一件已镶嵌了雕纹的装备。
		return
	end
	local EquipType_1 = LuaFnGetBagEquipType( sceneId,selfId,nPos )
	if EquipType_1 == 17 then
		x900014_DWLeveUp_Dark(sceneId,selfId,nPos,iToLevelSel,iToLevelSelEx)
		return
	end
	local _,nCreaterData = LuaFnGetItemCreator(sceneId, selfId, nPos);
	if nCreaterData == nil then
		x900014_NotifyTip( sceneId, selfId, "#{DWSJ_141202_21}")--请放入一件已镶嵌了雕纹的装备。
		return
	end
	local pos1,pos2,nType_1,nData_1,nType_2,nData_2 = strfind( nCreaterData,x900014_DW_DWSIGIN)
	if pos1 == nil or pos2 == nil then
		x900014_NotifyTip( sceneId, selfId, "#{DWSJ_141202_21}")--请放入一件已镶嵌了雕纹的装备。
		return
	end
	--雕纹是否满级
	local DWLevel_1 = tonumber(nData_1)
	local DWLevel_2 = tonumber(nData_2)
	if DWLevel_1 == 10 and DWLevel_2 == 10 then
		--满级
		x900014_NotifyTip( sceneId, selfId,"#{DWSJ_141202_22}")
		return
	end
	local nCost_1,nCost_2 = 0,0
	if iToLevelSel>0 and iToLevelSelEx>0 then
		--升级两个
		if iToLevelSel <= DWLevel_1 or iToLevelSelEx <= DWLevel_2 then
			x900014_NotifyTip( sceneId, selfId,"#{DWSJ_141202_24}") --所选择的升级雕纹等级必须大于原雕纹的等级。
			return
		end
		--2019-11-3 15:43:56 逍遥子 修正雕纹数量
		for i = DWLevel_1,iToLevelSel - 1 do
			nCost_1 = nCost_1 + x900014_DWInfo[nType_1][i][2]
		end
		for i = DWLevel_2,iToLevelSelEx - 1 do
			nCost_2 = nCost_2 + x900014_DWInfo[nType_2][i][2]
		end
--		nCost_1 = x900014_DWInfo[nType_1][iToLevelSel - 1][2]
--		nCost_2 = x900014_DWInfo[nType_2][iToLevelSelEx - 1][2]
		--
		DWLevel_1 = iToLevelSel
		DWLevel_2 = iToLevelSelEx
	elseif iToLevelSel>0 then
		--升级1号雕纹
		if iToLevelSel <= DWLevel_1 then
			x900014_NotifyTip( sceneId, selfId,"#{DWSJ_141202_24}")
			return
		end
		--2019-11-3 15:43:56 逍遥子 修正雕纹数量
		for i = DWLevel_1,iToLevelSel - 1 do
			nCost_1 = nCost_1 + x900014_DWInfo[nType_1][i][2]
		end
--		nCost_1 = x900014_DWInfo[nType_1][iToLevelSel - 1][2]
		--
		DWLevel_1 = iToLevelSel
	elseif iToLevelSelEx>0 then
		--升级2号雕纹
		if iToLevelSelEx <= DWLevel_2 then
			x900014_NotifyTip( sceneId, selfId,"#{DWSJ_141202_24}")
			return
		end
		--2019-11-3 15:43:56 逍遥子 修正雕纹数量
		for i = DWLevel_2,iToLevelSelEx - 1 do
			nCost_2 = nCost_2 + x900014_DWInfo[nType_2][i][2]
		end
--		nCost_2 = x900014_DWInfo[nType_2][iToLevelSelEx - 1][2]
		--
		DWLevel_2 = iToLevelSelEx
	end
--	x900014_NotifyTip( sceneId, selfId,"nCost_1 "..nCost_1)
--	x900014_NotifyTip( sceneId, selfId,"nCost_2 "..nCost_2)
	local nMaterialNum = LuaFnMtl_GetCostNum(sceneId, selfId,20310168, 20310166, 20310167)
	if nMaterialNum < nCost_1 + nCost_2 then
		x900014_NotifyTip( sceneId, selfId,"金蚕丝不足，无法继续进行升级操作！")
		return
	end
	local nRet = LuaFnMtl_CostMaterial(sceneId,selfId,nCost_1 + nCost_2,20310168, 20310166, 20310167)
	if nRet ~= 1 then
		BeginEvent( sceneId )
			AddText( sceneId, StringTable_GetData(347) )
		EndEvent( sceneId )
		DispatchMissionTips( sceneId, selfId )
		return
	end
	local nFinalData,sLevel_1,sLevel_2 = "","",""
	sLevel_1 = tostring(DWLevel_1)
	if DWLevel_1 < 10 then
		sLevel_1 = "0"..tostring(DWLevel_1)
	end
	sLevel_2 = tostring(DWLevel_2)
	if DWLevel_2 < 10 then
		sLevel_2 = "0"..tostring(DWLevel_2)
	end
	nFinalData = gsub(nCreaterData,"&DW%w%w%w%w%w%w","&DW"..nType_1..sLevel_1..nType_2..sLevel_2)
	LuaFnSetEquipItemCreatorEx( sceneId, selfId, nPos, nFinalData)
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	x900014_NotifyTip( sceneId, selfId, "雕纹升级成功" )--H雕纹融合成功！
	local szItemTransfer = GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos ))--GetBagItemTransfer( sceneId, selfId, nPos )
	local nGlobalMsg = ""
	if DWLevel_1 ~=  tonumber(nData_1) then
		nGlobalMsg = format("#H#{_INFOUSR%s}在#G洛阳#{_INFOAIM318,315,0,张降龙}#Y张降龙#H处，成功使用#G雕纹升级#H功能将蚀刻在#Y%s#H上的#Y%s#H升级到了#G%s级#H。",
					GetName(sceneId,selfId),
					szItemTransfer,
					x900014_DWInfo[nType_1][tonumber(nData_1)][1],
					tostring(DWLevel_1))
	else
		nGlobalMsg = format("#H#{_INFOUSR%s}在#G洛阳#{_INFOAIM318,315,0,张降龙}#Y张降龙#H处，成功使用#G雕纹升级#H功能将蚀刻在#Y%s#H上的#Y双极雕纹：%s·%s#H进行强化，并成功将#Y双极·%s#H提升到了#Y%s#H级#H。",
					GetName(sceneId,selfId),
					szItemTransfer,
					x900014_DWInfo[nType_1][tonumber(nData_1)][4],
					x900014_DWInfo[nType_2][tonumber(nData_2)][4],
					x900014_DWInfo[nType_2][tonumber(nData_2)][4],--这个后边字是一样的无所谓了
					tostring(DWLevel_2))
		--双极雕纹
	end
	AddGlobalCountNews(sceneId,nGlobalMsg);
end
--**********************************
--雕纹强化--极致修改契合官方雕纹且契合复古。
--**********************************
function x900014_DWQiangHua(sceneId,selfId,nPos,Num)
    local HaveJSC = LuaFnGetAvailableItemCount(sceneId,selfId,20310166)
	if Num > HaveJSC then
	   x900014_NotifyTip( sceneId, selfId, "金蚕丝不足，无法进行操作！")
	   return
	end
	--这里暗器强化跳转下。
	local EquipPoint	= LuaFnGetBagEquipType( sceneId, selfId, nPos )
	if EquipPoint == 17 then
	   x900014_DWLeveUp_Dark(sceneId,selfId,nPos,Num)
	   return
	end
	--	
	local _,nDWstr = LuaFnGetItemCreator(sceneId,selfId,nPos)--装备上雕纹的信息。
	local pos1,pos2,nType_1,nLevel_1,nData_2 = strfind( nDWstr,x900014_DW_DWSIGIN)
	if pos1 == nil and pos2 == nil then
	   x900014_NotifyTip( sceneId, selfId, "该装备还没有进行雕纹蚀刻，无法升级。")
	   return
	end
	--意外处理下
	if nLevel_1 == "00" then
	   return
	end
	--极致修改添加内容
	--得到等级需要金蚕丝数量
    local NextDW = 0 --多余出来的雕纹。
	local nDWduoyu_2 = "0000"
	local nDWLeve = tonumber(nLevel_1)
	local DWduoyu = tonumber(nData_2) + Num
    -- for i = 1,10 do  这种废除，只能正常+1 材料超出两级就有问题
	   -- if tonumber(nData_2) + Num >= x900014_DWInfo[nType_1][tonumber(nLevel_1)][2]  then
	      -- nDWLeve = nDWLeve + 1
		  -- NextDW = (tonumber(nData_2) + Num) - x900014_DWInfo[nType_1][tonumber(nLevel_1)][2]
		  -- break
	   -- else
		  -- NextDW = tonumber(nData_2) + Num
		  -- break
	   -- end	   
	-- end
	while (DWduoyu > x900014_DWInfo[nType_1][nDWLeve][2]) do
	    if DWduoyu >= x900014_DWInfo[nType_1][nDWLeve][2] then
		   DWduoyu = DWduoyu - x900014_DWInfo[nType_1][nDWLeve][2]
		   nDWLeve = nDWLeve + 1
		end
	end	
	if DWduoyu < 10 then
	   nDWduoyu_2 = "000"..tostring(DWduoyu)
	elseif DWduoyu < 100 then
	   nDWduoyu_2 = "00"..tostring(DWduoyu)
	elseif DWduoyu < 1000 then
	   nDWduoyu_2 = "0"..tostring(DWduoyu)
	elseif DWduoyu >= 1000 then
	   nDWduoyu_2 = tostring(DWduoyu)
	end
	--结束
	local nDWLeve_2
	if tonumber(nLevel_1) < 10 then
	   nDWLeve_2 = "0"..tostring(nDWLeve)
	end
	local ret = LuaFnDelAvailableItem(sceneId,selfId,20310166,Num)
	if ret ~= 1 then
	   x900014_NotifyTip( sceneId, selfId, "金蚕丝扣除失败，无法进行强化。")
	   return
	end
	local nFinalData = gsub(nDWstr,"&DW%w%w%w%w%w%w%w","&DW"..nType_1..nDWLeve_2..tostring(nDWduoyu_2))
    LuaFnSetEquipItemCreatorEx(sceneId,selfId,nPos,nFinalData)
    x900014_NotifyTip( sceneId, selfId, "恭喜您，雕纹强化成功")
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	local nGlobalMsg = ""
	local szItemTransfer = GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, nPos ))
	if nDWLeve > tonumber(nLevel_1) then
	nGlobalMsg = format("#H#{_INFOUSR%s}在#G洛阳#{_INFOAIM152,101,0,张降龙}#Y张降龙#H处，成功使用#G雕纹升级#H功能将蚀刻在#Y%s#H上的#Y%s#H升级到了#G%s级#H。",
					GetName(sceneId,selfId),
					szItemTransfer,
					x900014_DWInfo[nType_1][tonumber(nLevel_1)][1],
					tonumber(nDWLeve_2))
    AddGlobalCountNews(sceneId,nGlobalMsg)					
	end				
	return
end
--**********************************
--雕纹融合
--**********************************
function x900014_DWRongHe(sceneId,selfId,arg1,arg2,arg3)
	local EquipPoint	= LuaFnGetBagEquipType( sceneId, selfId, arg1 )
	local nMaterial = LuaFnGetItemTableIndexByIndex( sceneId, selfId, arg2 )
	local nDiaoWen = LuaFnGetItemTableIndexByIndex( sceneId, selfId, arg3 )
	if EquipPoint == 2 or EquipPoint == 8 then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_9}")
		return
	end
	if nMaterial ~= 38001002 and nMaterial ~= 38001003 then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_45}")--H请放入雕纹融合符。
		return
	end
	if x900014_DWValue[nDiaoWen][1] == nil then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_46}")--请放入雕纹。
		return
	end
	--2019-11-10 19:42:56 逍遥子 豪侠印特写
	if EquipPoint ~= 21 then
		if x900014_DWRuleTab[x900014_DWValue[nDiaoWen][1]][EquipPoint + 1] ~= 1 then
			x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_47}")--H只有相同装备位、不同颜色的两个雕纹才能进行融合。
			return
		end
	end
	if EquipPoint == 17 then
		x900014_DoDiaowenAction_Dark_RongHe(sceneId,selfId,arg1,arg2,arg3)
		return
	end
	--
	local _,nCreaterData = LuaFnGetItemCreator(sceneId, selfId, arg1);
	if nCreaterData == nil then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_44}")--H请先放入已蚀刻了一个雕纹的装备。
		return
	end
	local pos1,pos2,nType_1,nData_1,nType_2,nData_2 = strfind( nCreaterData,x900014_DW_DWSIGIN)
	if pos1 == nil or pos2 == nil then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_44}")--H请先放入已蚀刻了一个雕纹的装备。
		return
	end
	--校验雕纹类型
	--local nDW_Head = mod(floor(nDiaoWen/10),1000)
	local nDW_Head = x900014_DW_ToTable[nDiaoWen]
	if nDW_Head == nType_1 then
		x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_47}" )--H只有相同装备位、不同颜色的两个雕纹才能进行融合。
		return
	end
	--校验雕纹类型
	local nFinalData = ""
	local sDWLevel = "" --这里需要添加等级
	local nDWLevel = mod(nDiaoWen,10)
	if nDWLevel == 0 then
		nDWLevel = 10
	end
	if nDWLevel < 10 then
		sDWLevel = "0"..tostring(nDWLevel)
	else
		sDWLevel = nDWLevel
	end
	nType_2 = x900014_DW_ToTable[nDiaoWen]
	nData_2 = sDWLevel
	nFinalData = gsub(nCreaterData,"&DW%w%w%w%w%w%w","&DW"..nType_1..nData_1..nType_2..nData_2)   
	LuaFnSetEquipItemCreatorEx( sceneId, selfId, arg1, nFinalData)
	LuaFnDelAvailableItem(sceneId,selfId,nMaterial,1)--扣除雕纹融合符
	LuaFnDelAvailableItem(sceneId,selfId,nDiaoWen,1)--扣除雕纹
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	x900014_NotifyTip( sceneId, selfId, "#{SSXDW_140819_52}" )--H雕纹融合成功！
	local szItemTransfer = GetItemName(sceneId,LuaFnGetItemTableIndexByIndex( sceneId, selfId, arg1 ))--GetBagItemTransfer( sceneId, selfId, arg1 )
	local nGlobalMsg = "#H#{_INFOUSR"..GetName(sceneId,selfId).."}潜心钻研雕纹之奥秘，仅用一张#{_ITEMINFO38001002}，便成功地将#Y"..GetItemName(sceneId,nDiaoWen).."#H与已蚀刻在"..szItemTransfer.."之上的#Y"..x900014_DWInfo[nType_1][tonumber(nData_1)][1].."#H融合为#Y双极雕纹："..x900014_DWInfo[nType_1][tonumber(nData_1)][4].."·"..x900014_DWInfo[nType_2][tonumber(nData_2)][4].."（"..tonumber(nData_1).."级·"..tonumber(nData_2).."级）#H，此举之妙令众人赞叹不已！"
	AddGlobalCountNews(sceneId,nGlobalMsg);
end
--**********************************
--雕纹蚀刻
--**********************************
function x900014_DWShike(sceneId,selfId, arg1,arg2,arg3)
	local EquipPoint	= LuaFnGetBagEquipType( sceneId, selfId, arg1 )
	local nMaterial = LuaFnGetItemTableIndexByIndex( sceneId, selfId, arg2 )
	local nDiaoWen = LuaFnGetItemTableIndexByIndex( sceneId, selfId, arg3 )
	if EquipPoint == 2 or EquipPoint == 8 then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_9}")
		return
	end
	if nMaterial ~= 30503149 then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_8}")
		return
	end
--	local ret_judge = LuaFnIsJudgeApt( sceneId, selfId, arg1 )
--	if ret_judge ~= 1 then
--		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_22}")--未鉴定装备不能蚀刻。
--		return
--	end
	--开始检测雕纹类型和装备的对应关系
	if x900014_DWValue[nDiaoWen][1] == nil then
		x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_10}")--请放入雕纹。
		return
	end
	--豪侠印特写 2019-11-10 19:34:25 逍遥子
	if EquipPoint ~= 21 then
	    if EquipPoint == 18 then--极致修改，适配我这个08复古 18装备点
		   EquipPoint = 16
		end
		if x900014_DWRuleTab[x900014_DWValue[nDiaoWen][1]][EquipPoint + 1] ~= 1 then
			x900014_NotifyTip( sceneId, selfId, "#{ZBDW_091105_23}")--雕纹与装备不匹配，请重新放入。
			return
		end
	end
	if EquipPoint == 17 then --暗器特殊处理
		x900014_DoDiaowenAction_Dark(sceneId,selfId,arg1,arg2,arg3)
		return
	end
	local _,nCreaterData = LuaFnGetItemCreator(sceneId, selfId, arg1);
	if nCreaterData == nil then
		nCreaterData = ""
	end
	--2019-11-2 20:17:31 逍遥子 写法更改
	local nFinalData = ""
	local sDWLevel = "" --这里需要添加等级
	local nDWLevel = mod(nDiaoWen,10)
	if nDWLevel == 0 then
		nDWLevel = 10
	end
	if nDWLevel < 10 then
		sDWLevel = "0"..tostring(nDWLevel)
	else
		sDWLevel = nDWLevel;
	end
	local pos1,pos2,nType_1,nData_1,nType_2,nData_2 = strfind( nCreaterData,x900014_DW_DWSIGIN)
	if pos1 == nil or pos1 == nil then
		nFinalData = nCreaterData.."&DW"..x900014_DW_ToTable[nDiaoWen]..sDWLevel..strrep("0",4)
	else
		if nType_1 ~= "0" then
			x900014_NotifyTip( sceneId, selfId, "#{XZBDW_130730_01}" )
			return
		end
		--存在雕纹代码，直接覆盖
		nFinalData = gsub(nCreaterData,x900014_DW_DWSIGIN,"&DW"..x900014_DW_ToTable[nDiaoWen]..sDWLevel..strrep("0",4))
	end
	--武魂特写 雕纹绑定
	if EquipPoint == 10 then
		LuaFnItemBind(sceneId,selfId,arg1)
	end
	LuaFnSetEquipItemCreatorEx( sceneId, selfId, arg1, nFinalData)
	LuaFnDelAvailableItem(sceneId,selfId,nMaterial,1)
	LuaFnDelAvailableItem(sceneId,selfId,nDiaoWen,1)--扣除雕纹
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 149, 0)
	x900014_NotifyTip( sceneId, selfId, "恭喜你，蚀刻成功！" )
end
