--**********************************
--雕纹合成
--**********************************
function x900014_DWHecheng( sceneId, selfId, itemPos )
	local itemTableIndex = LuaFnGetItemTableIndexByIndex( sceneId, selfId, itemPos )
	local ret1,ret2 = GetDiaowenHechengMat(itemTableIndex)
	if ret1 ~= -1 then		     
		if LuaFnGetAvailableItemCount(sceneId, selfId,20310169) < ret1 then
			x900014_NotifyTip( sceneId, selfId, "丹青不足，请检查背包中未加锁的丹青是否足够！" )
			return
		end
	end
	if ret2 ~= -1 then
		if LuaFnGetAvailableItemCount(sceneId, selfId, 20502009) < ret2 then
			x900014_NotifyTip( sceneId, selfId, "黄纸不足，请检查背包中未加锁的黄纸是否足够！" )
			return
		end
	end
	if CostMoney(sceneId, selfId, x900014_g_needMoeny) == -1 then
		x900014_NotifyTip( sceneId, selfId, "#{ResultText_154}" )
		return
	end
	local nRet = LuaFnDelAvailableItem(sceneId,selfId,20310169,ret1)
	if nRet ~= 1 then
		BeginEvent( sceneId )
			AddText( sceneId, "所需丹青不足20个。")
		EndEvent( sceneId )
		DispatchMissionTips( sceneId, selfId )
		return
	end
	if LuaFnDelAvailableItem(sceneId,selfId,20502009,ret2) ~= 1 then
		BeginEvent( sceneId )
			AddText( sceneId, "所需黄纸不足20个。")
		EndEvent( sceneId )
		DispatchMissionTips( sceneId, selfId )	
	   return
	end
	if x900014_g_DWHeCheng[itemTableIndex] == nil then
		return
	end
	LuaFnEraseItem( sceneId, selfId, itemPos )
	
	local bagpos01 = TryRecieveItem( sceneId, selfId, x900014_g_DWHeCheng[itemTableIndex], 1)
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 148, 0)
	x900014_NotifyTip( sceneId, selfId, "恭喜你，成功合成了一个"..GetItemName( sceneId,x900014_g_DWHeCheng[itemTableIndex]) )
end

function x900014_MsgBox( sceneId, selfId, msg )
	BeginEvent( sceneId )
		AddText( sceneId, msg )
	EndEvent( sceneId )
	DispatchEventList( sceneId, selfId, -1 )
end

function x900014_DWShikeJC( sceneId, selfId, nPos )
	local nLevel_1,nLevel_2 = 0,0
	local _, nCreaterData = LuaFnGetItemCreator(sceneId, selfId, nPos);
	if nCreaterData == nil then
	    return nLevel_1,nLevel_2
	end
	local pos1,pos2,_,nData_1,_,nData_2 = strfind( nCreaterData,x900014_DW_DWSIGIN)
	if pos1 == nil or pos2 == nil then 
		return nLevel_1,nLevel_2
	end	
	if nData_1 ~= nil and nData_1 ~= "00" then
		nLevel_1 = tonumber(nData_1)
	end
	if nData_2 ~= nil and nData_2 ~= "00" then
		nLevel_2 = tonumber(nData_2)
	end
--	x900014_NotifyTip( sceneId, selfId, "nLevel_1 "..nLevel_1.." nLevel_2 "..nLevel_2 )
	return nLevel_1,nLevel_2
end	
